class BaseModel:
    def __init__(self, fields_set, data):
        self.__fields_set__ = fields_set
        self._data = data
        self.alias_map = {"name": "aliased_name"}
    def dict(self, by_alias=False, exclude_unset=False):
        items = self._data.items()
        if exclude_unset:
            items = [(k, v) for k, v in items if k in self.__fields_set__]
        if by_alias:
            items = [(self.alias_map.get(k, k), v) for k, v in items]
        return dict(items)

PYDANTIC_1 = True

def _prepare_response_content(res, *, exclude_unset):
    if isinstance(res, BaseModel):
        if PYDANTIC_1:
            return res.dict(by_alias=True, exclude_unset=exclude_unset)
        return res.dict(by_alias=True, skip_defaults=exclude_unset)
    elif isinstance(res, list):
        return [_prepare_response_content(i, exclude_unset=exclude_unset) for i in res]
    elif isinstance(res, dict):
        return {k: _prepare_response_content(i, exclude_unset=exclude_unset) for k, i in res.items()}
    return res

# single model, exclude_unset
m = BaseModel({"name", "price"}, {"name": "valid", "price": 1.0, "owner_ids": None})
assert _prepare_response_content(m, exclude_unset=True) == {"aliased_name": "valid", "price": 1.0}
# no exclude_unset
assert _prepare_response_content(m, exclude_unset=False) == {"aliased_name": "valid", "price": 1.0, "owner_ids": None}
# list of models
lst = [BaseModel({"name"}, {"name": "foo", "price": None, "owner_ids": None}),
       BaseModel({"name", "price"}, {"name": "bar", "price": 1.0, "owner_ids": None})]
assert _prepare_response_content(lst, exclude_unset=True) == [{"aliased_name": "foo"}, {"aliased_name": "bar", "price": 1.0}]
# dict of models
d = {"k1": lst[0], "k2": lst[1]}
assert _prepare_response_content(d, exclude_unset=True) == {"k1": {"aliased_name": "foo"}, "k2": {"aliased_name": "bar", "price": 1.0}}
# scalars pass through
assert _prepare_response_content(5, exclude_unset=True) == 5
print("all good")
